PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE station_readings (
    station_id TEXT PRIMARY KEY,
    name TEXT,
    lat REAL,
    lng REAL,
    sea_surface_temp REAL,
    temp_anomaly REAL,
    degree_heating_weeks REAL,
    bleaching_alert_level TEXT,
    risk_score INTEGER,
    status TEXT,
    source TEXT,
    last_updated TEXT,
    error TEXT
  );
COMMIT;
